package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import java.util.Date

/**
 * Code and documentation generated by Claude (Anthropic, Claude Opus 5.5). Estimated AI-generated share of this file: ~100%
 * Tests admins removing reviews through [InMemoryReviewRepository], and the [ReviewPolicy] helpers for malformed reviews.
 */
class ReviewRemovalTest {

    private var now = 1_000L
    private lateinit var repo: InMemoryReviewRepository

    @Before
    fun setUp() {
        repo = InMemoryReviewRepository(
            listOf(Campsite(campsiteId = "site1", ownerId = "owner")),
            clock = { Date(now++) },
        )
    }

    /** Posts a review and returns it as stored, i.e. as an admin would see it. */
    private fun post(userId: String, text: String, name: String = "Name"): Review {
        var saved: Review? = null
        repo.submitReview("site1", userId, name, text, onSuccess = { saved = it }, onFailure = { throw it })
        return saved!!
    }

    private fun remove(userId: String, expected: Review? = null, campsiteId: String = "site1"): Exception? {
        var error: Exception? = null
        var succeeded = false
        repo.removeReview(campsiteId, userId, expected, onSuccess = { succeeded = true }, onFailure = { error = it })
        assertTrue("exactly one callback should run", succeeded != (error != null))
        return error
    }

    private fun reviewers(): List<String> {
        var result: List<Review>? = null
        repo.getReviews("site1", onSuccess = { result = it }, onFailure = { throw it })
        return result!!.map { it.userId }
    }

    @Test
    fun removingDeletesOnlyThatReview() {
        val spam = post("spammer", "Buy now")
        post("fan", "Lovely")
        assertNull(remove("spammer", expected = spam))
        assertEquals(listOf("fan"), reviewers())
    }

    @Test
    fun removingWithoutExpectedTextRemovesWhateverIsStored() {
        post("spammer", "Buy now")
        assertNull(remove("spammer"))
        assertTrue(reviewers().isEmpty())
    }

    @Test
    fun editedReviewIsNotRemoved() {
        val seen = post("guest", "Rude words")
        post("guest", "Edited to be polite")
        assertEquals(ReviewPolicy.CHANGED_MESSAGE, remove("guest", expected = seen)?.message)
        assertEquals(listOf("guest"), reviewers())
    }

    @Test
    fun repostWithTheSameTextIsNotRemoved() {
        // The admin objected to the author's name; the author changes it and reposts the same text.
        val seen = post("guest", "Nice place", name = "Rude name")
        post("guest", "Nice place", name = "Sam")
        assertEquals(ReviewPolicy.CHANGED_MESSAGE, remove("guest", expected = seen)?.message)
        assertEquals(listOf("guest"), reviewers())
    }

    @Test
    fun removingTwiceFailsTheSecondTime() {
        val spam = post("spammer", "Buy now")
        assertNull(remove("spammer", spam))
        assertEquals("This review was already removed.", remove("spammer", spam)?.message)
    }

    @Test
    fun removingFromAnotherCampsiteLeavesThisOneAlone() {
        post("guest", "Hi")
        assertEquals("This review was already removed.", remove("guest", campsiteId = "other")?.message)
        assertEquals(listOf("guest"), reviewers())
    }

    @Test
    fun userCanPostAgainAfterRemoval() {
        val spam = post("guest", "Spam")
        assertNull(remove("guest", spam))
        post("guest", "A real review")
        assertEquals(listOf("guest"), reviewers())
    }

    @Test
    fun failuresAreReported() {
        val review = post("guest", "Hi")
        repo.failWith = IllegalStateException("offline")
        assertEquals("offline", remove("guest", review)?.message)
        repo.failWith = null
        assertEquals(listOf("guest"), reviewers())
    }

    @Test
    fun onlyReviewsWithTextAreShownToUsers() {
        assertTrue(ReviewPolicy.isShownToUsers(Review(text = "Nice")))
        assertFalse(ReviewPolicy.isShownToUsers(Review(text = "")))
        assertFalse(ReviewPolicy.isShownToUsers(Review(text = "   ")))
    }

    @Test
    fun parseStoredTextKeepsStringsAndBlanksAnythingElse() {
        assertEquals("hello", ReviewPolicy.parseStoredText("hello"))
        assertEquals("", ReviewPolicy.parseStoredText(null))
        assertEquals("", ReviewPolicy.parseStoredText(42L))
        assertEquals("", ReviewPolicy.parseStoredText(listOf("a")))
    }
}
